head.script:
scwin.gVar = {
    "cMandatory" : "",
    "cMaxlength" : "",
    "cMinlength" : "",
    "cMaxByteLength" : "",
    "cMinByteLength" : "",
    "cValue" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > M > validate]<br/>입력값에 대한 유효성 체크를 실행한 후 결과값을 반환합니다.",
    "validation" : [
        "mandatory, maxlength, minlength, maxByteLength, minByteLength 속성이 한 개 이상 설정되어야 실행됩니다.",
        "유효성 체크를 모두 통과한 경우 true 를 반환합니다.",
        "유효성 체크를 하나라도 통과하지 못한 경우 false 를 반환합니다.",
        "유효성 체크는 자동으로 실행되지 않으므로 스크립트에서 validator() 메소드를 직접 실행해야 합니다.",
        "mandatory, maxlength, minlength, maxByteLength, minByteLength 속성 순서로 유효성 체크가 실행됩니다.",
        "유효성 체크를 통과하지 못한 속성에서 체크가 중단됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값, 자체 값 selectbox 는 value)
    // 기본 : 5개 속성 모두 설정 + 입력값 abc (maxlength, minlength, maxByteLength, minByteLength 모두 실패하는 값)
    con_mandatory.setValue("2");
    con_maxlength.setValue("2");
    con_minlength.setValue("4");
    con_maxByteLength.setValue("2");
    con_minByteLength.setValue("6");
    con_value.setValue("abc");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 displaymessage=true 로 고정하고 유효성 체크 속성과 입력값은 위 조건에서 선택합니다\n[절차] 조건 선택 -> Target 재생성 (선택한 입력값으로 덮어씁니다) -> validate 버튼 클릭\n[확인] Target 재생성 직후나 target1 입력 후 바깥 영역 클릭 시에는 alert 이 뜨지 않고 validate 클릭 시에만 뜨는지\n[확인] alert 창의 문구 (어느 속성의 메시지인지, 메시지가 1개인지) 와 결과창의 validate() 반환값\n[참고] 순서 확인은 기본 조건 (5개 속성 + 입력값 abc) 에서 validate 후 앞 순서 속성을 하나씩 미설정으로 바꿔 재생성하며 반복합니다 (maxlength 설정 시 target1 에 직접 입력하면 값이 잘리므로 순서 확인 중에는 입력하지 않습니다)"', '', 'label1');

    // 조건 설정
    scwin.gVar["cMandatory"] = con_mandatory.getText();
    scwin.gVar["cMaxlength"] = con_maxlength.getValue();
    scwin.gVar["cMinlength"] = con_minlength.getValue();
    scwin.gVar["cMaxByteLength"] = con_maxByteLength.getValue();
    scwin.gVar["cMinByteLength"] = con_minByteLength.getValue();
    scwin.gVar["cValue"] = con_value.getValue();

    let properties = {
        mandatory : scwin.gVar["cMandatory"],
        maxlength : scwin.gVar["cMaxlength"],
        minlength : scwin.gVar["cMinlength"],
        maxByteLength : scwin.gVar["cMaxByteLength"],
        minByteLength : scwin.gVar["cMinByteLength"],
        displaymessage : "true",
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList);

    // 헬퍼가 넣은 초기값 secret 을 선택한 입력값으로 덮음 (maxlength 가 걸려 있어도 setValue 값은 잘리지 않음)
    if (scwin.gVar["cValue"] === "empty")
        target1.setValue("");
    else
        target1.setValue(scwin.gVar["cValue"]);
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// validate 실행 - validation 1, 2, 3, 5, 6 판정 출력 (실패 속성은 alert 의 시스템 기본 메시지로 확인)
scwin.btn_validate_onclick = function (e) {
    // password 는 화면으로 글자 수 확인이 불가하므로 판정 근거로 값 길이와 Byte 수를 함께 출력
    let strValue = target1.getValue() || "";
    let nLength = strValue.length;
    let nByte = WebSquare.util.getStringByteSize(strValue);

    let rtn = target1.validate();

    wf_body_bottom.getObj("scwin").setReturnValue("mandatory " + scwin.fn_disp(scwin.gVar["cMandatory"])
        + " / maxlength " + scwin.fn_disp(scwin.gVar["cMaxlength"])
        + " / minlength " + scwin.fn_disp(scwin.gVar["cMinlength"])
        + " / maxByteLength " + scwin.fn_disp(scwin.gVar["cMaxByteLength"])
        + " / minByteLength " + scwin.fn_disp(scwin.gVar["cMinByteLength"])
        + " / 입력값 " + nLength + "자 " + nByte + "byte"
        + " -> validate() 반환값 : " + rtn);
}
